UPDATE ccds_share_token
station_id = #{stationId}, token_hash = #{tokenHash}, expire_at = #{expireAt}, revoked_at = #{revokedAt}, created_by = #{createdBy}, gmt_modified = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE ccds_share_token
SET revoked_at = #{now}
WHERE station_id = #{stationId}
  AND expire_at > #{now}
  AND revoked_at IS NULL
